import cmath, math, random
from qubitfabric.simulation import estimate_expectation

# 朴素稠密矩阵参考实现
def reference(circuit, obs):
    n = circuit["qubit_count"]
    ops = circuit.get("operations", [])
    # 单比特门作用到态矢量
    def apply1(state, q, m):
        mask = 1 << q
        for i in range(len(state)):
            if not i & mask:
                j = i | mask
                a, b = state[i], state[j]
                state[i] = m[0][0]*a + m[0][1]*b
                state[j] = m[1][0]*a + m[1][1]*b
    state = [0j]*(1<<n); state[0] = 1+0j
    for op in ops:
        g = op["gate"]
        if g == "x": apply1(state, op["target"], [[0,1],[1,0]])
        elif g == "h":
            s = 1/math.sqrt(2); apply1(state, op["target"], [[s,s],[s,-s]])
        elif g == "rx":
            t = op["angle"]; apply1(state, op["target"],
                [[math.cos(t/2), -1j*math.sin(t/2)],[-1j*math.sin(t/2), math.cos(t/2)]])
        elif g == "rz":
            t = op["angle"]; apply1(state, op["target"], [[cmath.exp(-1j*t/2),0],[0,cmath.exp(1j*t/2)]])
        elif g == "cx":
            c, t = 1<<op["control"], 1<<op["target"]
            for i in range(len(state)):
                if i & c and not i & t:
                    state[i], state[i|t] = state[i|t], state[i]
    # 期望：构造 P 的稠密作用
    total = 0j
    P1 = {"I":[[1,0],[0,1]],"X":[[0,1],[1,0]],"Y":[[0,-1j],[1j,0]],"Z":[[1,0],[0,-1]]}
    for i in range(1<<n):
        for j in range(1<<n):
            # <i|P|j>
            amp = 1
            for q in range(n):
                p = P1[obs[q]]
                amp *= p[(i>>q)&1][(j>>q)&1]
            total += state[i].conjugate()*amp*state[j]
    return total.real

rng = random.Random(0)
paulis = "IXYZ"
for trial in range(30):
    n = rng.randint(0, 4)
    ops = []
    for _ in range(rng.randint(0, 8)):
        g = rng.choice(["x","h","rx","rz","cx"])
        if g in ("x","h"):
            ops.append({"gate": g, "target": rng.randrange(n)}) if n else None
        elif g in ("rx","rz"):
            if n: ops.append({"gate": g, "target": rng.randrange(n), "angle": rng.uniform(-7,7)})
        else:
            if n >= 2:
                c, t = rng.sample(range(n), 2)
                ops.append({"gate":"cx","control":c,"target":t})
    circuit = {"qubit_count": n, "operations": ops}
    obs_list = ["".join(rng.choice(paulis) for _ in range(n)) for _ in range(3)]
    got = estimate_expectation(circuit, obs_list)
    for entry, obs in zip(got["results"], obs_list):
        ref = reference(circuit, obs)
        assert abs(entry["expectation"] - ref) < 1e-9, (trial, obs, entry["expectation"], ref)
print("30 random circuits x 3 observables: all match dense reference")

# 采样模式 seed 省略也能运行
r = estimate_expectation({"qubit_count":1,"operations":[{"gate":"h","target":0}]}, ["Z"], shots=100)
assert r["results"][0]["counts"]["plus_one"] + r["results"][0]["counts"]["minus_one"] == 100
print("sampled mode without seed ok")
